from pathlib import Path
p=Path('work/pocket-research/compile.cjs');s=p.read_text(encoding='utf-8');i=s.index(' // Independent printed clauses')
s=s[:i]+r'''
 if(text==="1 Special Condition from among Asleep, Burned, Confused, Paralyzed, and Poisoned is chosen at random, and your opponent's Active Pokémon is now affected by that Special Condition. Any Special Conditions already affecting that Pokémon will not be chosen.")return[hit,{kind:'randomStatus',statuses:['Asleep','Burned','Confused','Paralyzed','Poisoned']}];
 if((m=text.match(/^Choose a spot from among your opponent's Active Spot and Bench\. At the end of your opponent's next turn, do (\d+) damage to the Pokémon in the spot you chose\.$/)))return[hit,{kind:'chooseSpot',amount:+m[1]}];
 if(text==="Discard all Energy from this Pokémon. Choose a spot from among your opponent's Active Spot and Bench. At the end of your opponent's next turn, Knock Out the Pokémon in the spot you chose.")return[hit,{kind:'discardEnergy',amount:'all'},{kind:'chooseSpot',knockout:true}];
 if((m=text.match(/^At the end of your opponent's next turn, do (\d+) damage to the Defending Pokémon\.$/)))return[hit,{kind:'lock',opponent:true,effect:'delayedDamage',amount:+m[1]}];
 if((m=text.match(/^During your next turn, attacks used by your (?:\[([A-Z])\] )?Pokémon do \+(\d+) damage to your opponent's Active Pokémon\.$/)))return[hit,{kind:'attackBonus',amount:+m[2],type:m[1],nextOwn:true}];
 if((m=text.match(/^If this is the first time this Pokémon has used an attack after coming into play, this attack does (\d+) more damage, and your opponent's Active Pokémon is now Paralyzed\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[1],predicate:{test:'firstAttack'}},{kind:'when',predicate:{test:'firstAttack'},then:[{kind:'status',status:'Paralyzed'}]}];
 if(text==="If this is the first time this Pokémon has used an attack after coming into play, during your opponent's next turn, they can't use any Trainer cards from their hand.")return[hit,{kind:'when',predicate:{test:'firstAttack'},then:[{kind:'playerLock',effect:'Trainer'}]}];
 if((m=text.match(/^If (.+) is on your Bench, this attack also does (\d+) damage to each of your opponent's Benched Pokémon\.$/)))return[hit,{kind:'when',predicate:{test:'benchName',name:m[1]},then:[{kind:'benchDamage',amount:+m[2]}]}];
 if(text==="Switch in 1 of your opponent's Benched Pokémon to the Active Spot. If you do, this attack does 50 damage to the new Active Pokémon.")return[{kind:'choosePokemon',side:'opponent',bench:true,optional:true,next:[{kind:'switch'},{kind:'damage',amount:50}]}];
 if(text==="You can use this attack only if you have Uxie and Azelf on your Bench. Discard all Energy from this Pokémon.")return[{kind:'attackRequirement',predicate:{test:'benchNames',names:['Uxie','Azelf']}},hit,{kind:'discardEnergy',amount:'all'}];
 if((m=text.match(/^If this Pokémon has at least (\d+) extra \[([A-Z])\] Energy attached, this attack also does (\d+) damage to (\d+|1) of your opponent's Benched Pokémon\.$/)))return[hit,{kind:'when',predicate:{test:'extraEnergy',count:+m[1],type:m[2],cost:context.cost||[]},then:[{kind:'chooseDamageRepeated',count:+m[4],amount:+m[3],bench:true}]}];
 if(text==="This attack does 20 damage to 1 of your opponent's Pokémon for each Energy attached to that Pokémon.")return[{kind:'choosePokemon',side:'opponent',next:[{kind:'damageTo',perEnergy:true,amount:20}]}];
 if((m=text.match(/^If this Pokémon was damaged by an attack during your opponent's last turn while it was in the Active Spot, this attack does (\d+) more damage\.$/)))return[{kind:'conditionalDamage',base:+damage||0,amount:+m[1],predicate:{test:'damagedLastTurn'}}];
 if(text==="Change the type of a random Energy attached to your opponent's Active Pokémon to 1 of the following at random: [G], [R], [W], [L], [P], [F], [D], or [M].")return[hit,{kind:'changeEnergyType',opponent:true}];
 if(text==="Change the type of the next Energy that will be generated for your opponent to 1 of the following at random: [G],[R],[W],[L],[P],[F],[D], or [M].")return[hit,{kind:'changeNextEnergy',opponent:true}];
 if(text==='Discard 2 cards from your hand. If you can\'t discard 2 cards, this attack does nothing.')return[{kind:'collect',min:2,max:2,optional:true,next:[{kind:'discardCollectedDamage',base:+damage||0,amount:0}]}];
 if(text==="Discard up to 2 Pokémon Tool cards from your hand. This attack does 50 damage for each card you discarded in this way.")return[{kind:'collect',subtype:'Tool',max:2,next:[{kind:'discardCollectedDamage',base:0,amount:50}]}];
 if((m=text.match(/^You may discard (?:1 of your Benched Basic \[([A-Z])\] Pokémon\. If you do, this attack does (\d+) more damage|any number of your Benched \[([A-Z])\] Pokémon\. This attack does (\d+) more damage for each Benched Pokémon you discarded in this way)\.$/)))return[{kind:'collect',zone:'pokemon',bench:true,type:m[1]||m[3],stage:m[1]?0:undefined,max:m[1]?1:3,next:[{kind:'sacrificeDamage',base:+damage||0,amount:+m[2]||+m[4]}]}];
 if(text==="This attack does 20 damage to each of your opponent's Pokémon. During your next turn, this Pokémon's Wild Spin attack does +20 damage to each of your opponent's Pokémon.")return[{kind:'damage',amount:20},{kind:'benchDamage',amount:20},{kind:'lock',effect:'namedBonus',name:'Wild Spin',amount:20,nextOwn:true,benchAlso:true}];
 if(text==="Flip a coin. If heads, your opponent reveals their hand. Choose a Supporter card you find there and discard it.")return[hit,{kind:'condition',then:[{kind:'revealHand',opponent:true},{kind:'chooseCard',opponent:true,subtype:'Supporter',optional:true,next:[{kind:'discardChosen'}]}]}];
 if(text==="Flip a coin. If heads, look at a random card from your opponent's hand and shuffle it into their deck.")return[hit,{kind:'condition',then:[{kind:'randomHand',opponent:true}]}];
 if(text==="Flip a coin. If heads, your opponent shuffles their Active Pokémon back into their deck.")return[hit,{kind:'condition',then:[{kind:'bounce',opponent:true,active:true,destination:'deck',optional:true}]}];
 if(text==="Flip a coin. If heads, put your opponent's Active Pokémon into their hand.")return[hit,{kind:'condition',then:[{kind:'bounce',opponent:true,active:true,destination:'hand',optional:true}]}];
 if(text==="Flip a coin. If heads, discard your opponent's Active Pokémon.")return[hit,{kind:'condition',then:[{kind:'bounce',opponent:true,active:true,destination:'discard'}]}];
 if(text==="You may shuffle this Pokémon and all attached cards into your deck.")return[hit,{kind:'chooseMode',modes:[{label:'Keep in play',program:[]},{label:'Shuffle into deck',program:[{kind:'bounce',destination:'deck',allAttached:true}]}]}];
 if(text==="Your opponent's Active Pokémon is now Poisoned and Paralyzed. Shuffle this Pokémon and all attached cards into your deck.")return[hit,{kind:'status',status:'Poisoned'},{kind:'status',status:'Paralyzed'},{kind:'bounce',destination:'deck',allAttached:true}];
 if(text==="Your opponent reveals a random card from their hand and shuffles it into their deck. Shuffle this Pokémon into your deck.")return[hit,{kind:'randomHand',opponent:true},{kind:'bounce',destination:'deck'}];
 if(text==="If any of your Pokémon were Knocked Out by damage from an attack during your opponent's last turn, your opponent's Active Pokémon is now Paralyzed.")return[hit,{kind:'when',predicate:{test:'revenge'},then:[{kind:'status',status:'Paralyzed'}]}];
 if(text==="If any of your Pokémon were Knocked Out by damage from an attack during your opponent's last turn, this attack does 60 more damage, and your opponent's Active Pokémon is now Paralyzed.")return[{kind:'conditionalDamage',base:+damage||0,amount:60,predicate:{test:'revenge'}},{kind:'when',predicate:{test:'revenge'},then:[{kind:'status',status:'Paralyzed'}]}];
 if(text==='Discard 2 random Energy from among the Energy attached to all of your Pokémon.')return[hit,{kind:'randomGlobalEnergy',own:true,amount:2}];
 if((m=text.match(/^Move (all|\d+)(?: \[([A-Z])\]| random)? Energy from this Pokémon to 1 of your Benched Pokémon\.$/)))return[hit,{kind:'choosePokemon',bench:true,optional:true,next:[{kind:'moveSelfToChosen',amount:m[1]==='all'?'all':+m[1],type:m[2],random:text.includes('random')}]}];
 if(text==='If a Stadium is in play, your opponent\'s Active Pokémon is now Burned.')return[hit,{kind:'when',predicate:{test:'stadium'},then:[{kind:'status',status:'Burned'}]}];
 if(text==='Take a random Energy from among [G], [R], [W], [L], [P], [F], [D], and [M] Energy from your Energy Zone and attach it to 1 of your Benched Pokémon.')return[hit,{kind:'choosePokemon',bench:true,optional:true,next:[{kind:'zoneEnergy',amount:1,randomType:true}]}];
 if(text==="Discard all Energy from this Pokémon. Knock Out your opponent's Active Pokémon.")return[hit,{kind:'discardEnergy',amount:'all'},{kind:'knockOut'}];
 if(text==="If this Pokémon evolved from Dunsparce during this turn, discard 2 random Energy from your opponent's Active Pokémon.")return[hit,{kind:'when',predicate:{test:'evolvedFrom',name:'Dunsparce'},then:[{kind:'randomEnergyDiscard',opponent:true,amount:2}]}];
 if(text==='Discard 3 [W] Energy from this Pokémon, and this attack does 50 damage to each of your opponent\'s Pokémon.')return[{kind:'discardEnergy',amount:3,type:'W'},{kind:'damage',amount:50},{kind:'benchDamage',amount:50}];
 if((m=text.match(/^Discard the top card of your deck(?:, and if|\. If) that card is (?:an? (Item)|a \[([A-Z])\] Pokémon),? this attack does (\d+) more damage\.$/)))return[{kind:'discardTopDamage',base:+damage||0,amount:+m[3],...(m[1]?{subtype:'Item'}:{category:'Pokemon',type:m[2]})}];
 if(text==='If your opponent\'s Active Pokémon has “Team Rocket” in its name, this attack does 70 more damage.')return[{kind:'conditionalDamage',base:+damage||0,amount:70,predicate:{test:'opponentNameContains',name:'Team Rocket'}}];
 if(text==='If your opponent\'s Pokémon is Knocked Out by damage from this attack, this Pokémon also does 50 damage to itself.')return[hit,{kind:'recoilIfKO',amount:50}];
 if(text==='Flip 3 coins. For each heads, a card is chosen at random from your opponent\'s hand. Your opponent reveals that card and shuffles it into their deck.')return[hit,{kind:'countCoins',count:3,then:{kind:'coinHandShuffle'}}];
 if(text==='Flip 2 coins. If both of them are heads, your opponent\'s Active Pokémon is Knocked Out.')return[hit,{kind:'allHeads',count:2,next:[{kind:'knockOut'}]}];
 if(text==='Flip 2 coins. If both of them are heads, discard your opponent\'s Active Pokémon.')return[hit,{kind:'allHeads',count:2,next:[{kind:'bounce',opponent:true,active:true,destination:'discard'}]}];
 if(text==='Flip a coin. If tails, discard 2 random Energy from this Pokémon.')return[hit,{kind:'condition',then:[],else:[{kind:'randomEnergyDiscard',amount:2}]}];
 if(text==='If your opponent\'s Active Pokémon is an evolved Pokémon, devolve it by putting the highest Stage Evolution card on it into your opponent\'s hand.')return[hit,{kind:'devolve'}];
 if(text==='If this Pokémon has damage on it, this attack can be used for 1 [L] Energy.')return[{kind:'specialCost',predicate:{test:'woundedSelf'},cost:['L']},hit];
 if(text==='If you have no cards in your deck, this attack can be used for 1 [W] Energy.')return[{kind:'specialCost',predicate:{test:'emptyDeck'},cost:['W']},hit];
 if(text==='Choose either Poisoned or Confused. Your opponent\'s Active Pokémon is now affected by that Special Condition.')return[hit,{kind:'chooseMode',modes:['Poisoned','Confused'].map(status=>({label:status,program:[{kind:'status',status}]}))}];
 if(text==='During your opponent\'s next turn, if they attach Energy from their Energy Zone to the Defending Pokémon, that Pokémon will be Asleep.')return[hit,{kind:'lock',opponent:true,effect:'zoneSleep'}];
 if(text==='During your opponent\'s next turn, if this Pokémon is in the Active Spot when your opponent\'s Active Pokémon retreats, this attack does 40 damage to the new Active Pokémon.')return[hit,{kind:'lock',effect:'retreatPunish',amount:40}];
 if(text==='1 of your opponent\'s Active Pokémon\'s attacks is chosen at random. During your opponent\'s next turn, that Pokémon can\'t use the chosen attack.')return[hit,{kind:'randomAttackLock'}];
 if((m=text.match(/^Reveal the top (\d+) cards of your deck\. This attack does (\d+) damage for each Pokémon (with a Retreat Cost of 3 or more you find there|you find there that has “Team Rocket” in its name)\. Shuffle the revealed cards back into your deck\.$/)))return[{kind:'revealTopDamage',count:+m[1],amount:+m[2],minRetreat:m[3].startsWith('with')?3:undefined,nameContains:m[3].startsWith('you')?'Team Rocket':undefined}];
 if(text==='Discard a [W] Energy from this Pokémon, and this attack also does 40 damage to 1 of your opponent\'s Benched Pokémon.')return[hit,{kind:'discardEnergy',type:'W',amount:1},{kind:'choosePokemon',side:'opponent',bench:true,optional:true,next:[{kind:'damageTo',amount:40}]}];
 if(text==='Discard an Energy from this Pokémon, and this attack also does 20 damage to each of your opponent\'s Benched Pokémon.')return[hit,{kind:'discardEnergy',amount:1},{kind:'benchDamage',amount:20}];
 if(text==='Flip a coin. If heads, this attack also does 40 damage to 1 of your opponent\'s Benched Pokémon.')return[hit,{kind:'condition',then:[{kind:'choosePokemon',side:'opponent',bench:true,optional:true,next:[{kind:'damageTo',amount:40}]}]}];
 if(text==='Flip a coin. If heads, switch in 1 of your opponent\'s Benched Pokémon to the Active Spot.')return[hit,{kind:'condition',then:[{kind:'choosePokemon',side:'opponent',bench:true,optional:true,next:[{kind:'switch'}]}]}];
 if(text==='Flip 3 coins. For each heads, discard a [R] Energy from this Pokémon. This attack does 30 more damage for each [R] Energy you discarded in this way.')return[{kind:'countCoins',count:3,then:{kind:'coinDiscardDamage',type:'R',base:+damage||0,amount:30}}];
''' +s[i:];p.write_text(s,encoding='utf-8')
